import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import PartnershipModal from '../../homepage/components/PartnershipModal';
import SubmitOpportunityModal from '../../homepage/components/SubmitOpportunityModal';

const CTASection = ({ data }) => {
  const navigate = useNavigate();
  const [isPartnershipModalOpen, setIsPartnershipModalOpen] = useState(false);
  const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
  if (!data) return null;

  const handleAction = (link, title, buttonText) => {
    // Robust check for WhatsApp links to ensure they always use the correct official link
    let finalLink = link;
    const isWhatsApp =
      title?.toLowerCase()?.includes('whatsapp') ||
      buttonText?.toLowerCase()?.includes('whatsapp') ||

      link?.toLowerCase()?.includes('wa.me') ||
      link?.toLowerCase()?.includes('whatsapp.com');

    if (isWhatsApp) {
      finalLink = 'https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V';
    }

    if (finalLink?.startsWith('http')) {
      window.open(finalLink, '_blank');
    } else if (finalLink === 'modal:partnership') {
      setIsPartnershipModalOpen(true);
    } else if (finalLink === 'modal:submission') {
      setIsSubmitModalOpen(true);
    } else if (finalLink) {
      navigate(finalLink);
    }
  };

  return (
    <section className="py-20 md:py-28 bg-gradient-to-br from-white via-blue-50/50 to-brand-blue/5 dark:from-[#0f172a] dark:via-[#1e293b] dark:to-[var(--color-brand-blue)] text-slate-900 dark:text-white transition-colors duration-500 relative overflow-hidden">
      <div className="absolute inset-0 opacity-10 dark:opacity-20 pointer-events-none">
        <div className="absolute top-10 right-10 w-64 h-64 bg-accent/20 rounded-full blur-3xl"></div>
        <div className="absolute bottom-10 left-10 w-96 h-96 bg-[var(--color-brand-purple)]/20 rounded-full blur-3xl"></div>
      </div>
      <div className="relative max-w-7xl mx-auto px-4 md:px-6 lg:px-8 z-10">
        <div className="text-center mb-16 md:mb-24">
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-black mb-6 tracking-tight leading-tight text-slate-900 dark:text-white italic">
            {data.title}
          </h2>
          <p className="text-base md:text-lg lg:text-xl text-slate-600 dark:text-white/90 max-w-3xl mx-auto font-medium">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
          {data.actions?.map((action, index) => (
            <div key={index} className="bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-3xl p-8 md:p-10 border border-white dark:border-white/10 shadow-xl dark:shadow-none hover:-translate-y-2 transition-all duration-500 group">
              <div className="w-16 h-16 md:w-20 md:h-20 rounded-2xl bg-primary/10 dark:bg-white/20 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform shadow-lg shadow-black/5">
                <Icon name={action?.icon} size={32} className="text-primary dark:text-white" />
              </div>

              <h3 className="text-xl md:text-3xl font-black mb-4 italic leading-tight text-slate-900 dark:text-white">
                {action?.title}
              </h3>

              <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 mb-8 leading-relaxed font-medium">
                {action?.description}
              </p>

              <Button
                variant="default"
                fullWidth
                onClick={() => handleAction(action.link, action.title, action.buttonText)}
                className="bg-primary dark:bg-white text-white dark:text-[#0f172a] hover:bg-secondary dark:hover:bg-secondary hover:text-white dark:hover:text-white border-none font-black italic py-4"
              >
                {action?.buttonText}
              </Button>
            </div>
          ))}
        </div>

        <div className="mt-16 md:mt-24 text-center">
          <div className="inline-flex flex-col sm:flex-row items-center gap-6 sm:gap-12 px-8 md:px-12 py-6 md:py-8 bg-white/50 dark:bg-white/10 backdrop-blur-xl rounded-[2rem] border border-white dark:border-white/10 shadow-xl dark:shadow-none">
            {data.summaryStats?.map((s, idx) => (
              <div key={idx} className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-secondary/10 flex items-center justify-center">
                  <Icon name={s.icon} size={24} className="text-secondary" />
                </div>
                <div className="text-left">
                  <div className="text-2xl md:text-4xl font-black text-slate-900 dark:text-white leading-none mb-1">{s.value}</div>
                  <div className="text-xs md:text-sm font-bold uppercase tracking-widest text-slate-500 dark:text-white/60">{s.label}</div>
                </div>
                {idx < data.summaryStats.length - 1 && <div className="hidden sm:block w-px h-12 bg-slate-200 dark:bg-white/20 ml-8"></div>}
              </div>
            ))}
          </div>
        </div>
      </div>

      <PartnershipModal
        isOpen={isPartnershipModalOpen}
        onClose={() => setIsPartnershipModalOpen(false)}
      />
      <SubmitOpportunityModal
        isOpen={isSubmitModalOpen}
        onClose={() => setIsSubmitModalOpen(false)}
      />
    </section>
  );
};

export default CTASection;