import React from 'react';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';


const ImpactMetrics = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-32 md:py-48 bg-slate-900 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-primary/5 rounded-full blur-3xl -mr-48 -mt-48" />
      <div className="absolute bottom-0 left-0 w-96 h-96 bg-secondary/5 rounded-full blur-3xl -ml-48 -mb-48" />

      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 relative z-10">
        <div className="text-center mb-24 md:mb-32">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-full mb-8 backdrop-blur-md">
            <Icon name="BarChart3" size={20} className="text-secondary" />
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white">Global Metrics</span>
          </div>
          <h2 className="text-4xl md:text-6xl lg:text-7xl font-black text-white mb-8 tracking-tighter italic leading-[0.9]">
            {data.title}
          </h2>
          <p className="text-xl md:text-2xl text-slate-400 max-w-4xl mx-auto font-medium leading-relaxed">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 md:gap-12 mb-32 md:mb-48">
          {data.metrics?.map((metric, index) => (
            <div key={index} className="bg-white/5 backdrop-blur-3xl rounded-[3rem] p-10 md:p-12 border border-white/5 hover:border-white/10 transition-all duration-700 shadow-2xl group">
              <div className="flex flex-col items-start gap-8">
                <div className="w-20 h-20 rounded-[2rem] flex items-center justify-center group-hover:scale-110 group-hover:rotate-6 transition-all duration-500 border border-white/10 shadow-2xl" style={{ backgroundColor: `${metric?.color}15` }}>
                  <Icon name={metric?.icon} size={36} color={metric?.color} />
                </div>
                <div className="flex-1">
                  <div className="text-5xl md:text-6xl font-black mb-4 tracking-tighter italic leading-none" style={{ color: metric?.color }}>
                    {metric?.value}
                  </div>
                  <div className="text-2xl font-black text-white mb-4 italic tracking-tight">
                    {metric?.label}
                  </div>
                  <div className="text-lg text-slate-400 font-medium leading-relaxed">
                    {metric?.description}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mb-12 md:mb-16">
          <h3 className="text-4xl md:text-6xl font-black text-white text-center mb-24 md:mb-32 tracking-tighter italic leading-[0.9]">
            Scholar <span className="bg-gradient-to-r from-secondary to-brand-blue bg-clip-text text-transparent">Success</span> Stories
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 md:gap-12">
            {data.testimonials?.map((testimonial, index) => (
              <div key={index} className="bg-white/5 backdrop-blur-3xl rounded-[3rem] p-10 md:p-12 border border-white/5 hover:border-white/10 transition-all duration-700 shadow-2xl flex flex-col h-full relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                   <Icon name="Quote" size={80} className="text-secondary" />
                </div>
                
                <div className="flex items-center gap-6 mb-10 relative z-10">
                  <div className="w-20 h-20 md:w-24 md:h-24 rounded-full overflow-hidden shrink-0 ring-4 ring-white/10 shadow-2xl">
                    <Image
                      src={testimonial?.image}
                      alt={testimonial?.imageAlt || testimonial?.author}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div>
                    <div className="font-black text-white text-xl italic leading-tight mb-1">{testimonial?.author}</div>
                    <div className="text-[10px] font-black text-secondary uppercase tracking-[0.2em]">{testimonial?.role}</div>
                  </div>
                </div>

                <p className="text-lg text-slate-300 leading-relaxed italic font-medium flex-1 relative z-10">
                  "{testimonial?.quote}"
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default ImpactMetrics;