import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../services/supabaseService';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import HeroSection from './components/HeroSection';
import MissionSection from './components/MissionSection';
import VerificationProcess from './components/VerificationProcess';
import TeamSection from './components/TeamSection';
import ImpactMetrics from './components/ImpactMetrics';
import PartnersSection from './components/PartnersSection';
import CommunityGuidelines from './components/CommunityGuidelines';
import DisclaimerSection from './components/DisclaimerSection';
import CTASection from './components/CTASection';
import CPMDefense from './components/CPMDefense';

const About = () => {
  const aboutData = useSelector((state) => state.content.about);
  const [liveStats, setLiveStats] = useState({ users: 0, opportunities: 0, loading: true });
  const [teamVisible, setTeamVisible] = useState(true);
  const [impactVisible, setImpactVisible] = useState(true);
  const [partnersVisible, setPartnersVisible] = useState(true);
  const [pressVisible, setPressVisible] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [userCount, opportunities, siteSettings] = await Promise.all([
          supabaseService.getUserCount(),
          supabaseService.getOpportunities(),
          supabaseService.getSiteSettings().catch(() => null)
        ]);
        setLiveStats({
          users: userCount,
          opportunities: opportunities.length,
          loading: false
        });
        if (siteSettings) {
          setTeamVisible(siteSettings.team_section_visible !== false);
          setImpactVisible(siteSettings.impact_visible !== false);
          setPartnersVisible(siteSettings.partners_visible !== false);
          setPressVisible(siteSettings.press_visible !== false);
        }
      } catch (error) {
        console.error("Error fetching live about stats:", error);
        setLiveStats(prev => ({ ...prev, loading: false }));
      }
    };

    fetchStats();
    window.scrollTo(0, 0);

    // Set up Realtime Subscription for Users
    const usersChannel = supabaseService.subscribeToTable('profiles', (payload) => {
      if (payload.eventType === 'INSERT') {
        setLiveStats(prev => ({ ...prev, users: prev.users + 1 }));
      }
      if (payload.eventType === 'DELETE') {
        setLiveStats(prev => ({ ...prev, users: Math.max(0, prev.users - 1) }));
      }
    });

    // Set up Realtime Subscription for Opportunities
    const oppsChannel = supabaseService.subscribeToTable('opportunities', (payload) => {
      if (payload.eventType === 'INSERT') {
        setLiveStats(prev => ({ ...prev, opportunities: prev.opportunities + 1 }));
      }
      if (payload.eventType === 'DELETE') {
        setLiveStats(prev => ({ ...prev, opportunities: Math.max(0, prev.opportunities - 1) }));
      }
    });

    return () => {
      supabaseService.unsubscribe(usersChannel);
      supabaseService.unsubscribe(oppsChannel);
    };
  }, []);

  const getStatValue = (liveValue, label) => {
    return liveStats.loading ? "..." : `${(liveValue || 0).toLocaleString()}+`;
  };

  if (!aboutData) {
    return (
      <div className="min-h-screen bg-[var(--color-background)] flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[var(--color-background)] flex flex-col">
      <Header />

      <main className="flex-1">
        <HeroSection data={{
          ...aboutData.hero,
          badgeText: liveStats.loading ? "Loading..." : `Trusted by ${(liveStats.users || 0).toLocaleString()}+ Community Members`,
          stats: aboutData.hero.stats?.map(s => {
            const label = s.label?.toLowerCase() || '';
            if (label.includes('member') || label.includes('user') || label.includes('subscriber') || label.includes('people'))
              return { ...s, value: getStatValue(liveStats.users, s.label) };
            if (label.includes('opp') || label.includes('listing') || label.includes('scholarship') || label.includes('posted'))
              return { ...s, value: getStatValue(liveStats.opportunities, s.label) };
            return s;
          })
        }} />
        <MissionSection data={aboutData.mission} />
        <CPMDefense />
        <VerificationProcess data={aboutData.verification} />
        {teamVisible && <TeamSection data={aboutData.team} />}
        {impactVisible && (
        <ImpactMetrics data={{
          ...aboutData.impact,
          metrics: aboutData.impact.metrics?.map(m => {
            const label = m.label?.toLowerCase() || '';
            if (label.includes('member') || label.includes('user') || label.includes('people'))
              return { ...m, value: getStatValue(liveStats.users, m.value) };
            if (label.includes('opp') || label.includes('listing') || label.includes('scholarship') || label.includes('posted'))
              return { ...m, value: getStatValue(liveStats.opportunities, m.value) };
            return m;
          })
        }} />
        )}
        {partnersVisible && (
        <PartnersSection data={aboutData.partners} pressVisible={pressVisible} />
        )}
        <CommunityGuidelines data={aboutData.guidelines} />
        <DisclaimerSection data={aboutData.disclaimer} />
        <CTASection data={{
          ...aboutData.cta,
          summaryStats: aboutData.cta.summaryStats?.map(s => {
            const label = s.label?.toLowerCase() || '';
            if (label.includes('member') || label.includes('user') || label.includes('subscriber') || label.includes('people'))
              return { ...s, value: getStatValue(liveStats.users, s.value) };
            if (label.includes('opp') || label.includes('listing') || label.includes('scholarship') || label.includes('posted'))
              return { ...s, value: getStatValue(liveStats.opportunities, s.value) };
            return s;
          })
        }} />
      </main>

      <Footer />
    </div>
  );
};

export default About;