import React from 'react';
import Icon from '../../../components/AppIcon';

const MissionSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-32 md:py-48 bg-slate-950 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-blue-600/5 blur-[150px] rounded-full" />

      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 relative z-10">
        <div className="text-center mb-24 md:mb-32">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-full mb-8 backdrop-blur-md">
            <Icon name="Compass" size={20} className="text-secondary" />
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white">Our Manifesto</span>
          </div>
          <h2 className="text-4xl md:text-6xl lg:text-7xl font-black text-white mb-8 tracking-tighter italic leading-[0.9]">
            {data.title}
          </h2>
          <p className="text-xl md:text-2xl text-slate-400 max-w-4xl mx-auto font-medium leading-relaxed">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 md:gap-12">
          {data.messages?.map((item, index) => (
            <div key={index} className="group relative bg-white/5 backdrop-blur-3xl rounded-[3rem] p-10 md:p-12 border border-white/5 hover:border-secondary/30 transition-all duration-700 shadow-2xl overflow-hidden">
              <div className="absolute top-0 right-0 w-32 h-32 bg-secondary/5 rounded-full -mr-16 -mt-16 blur-2xl group-hover:bg-secondary/10 transition-colors"></div>

              <div className="relative">
                <div className="w-20 h-20 rounded-[2rem] bg-white/5 flex items-center justify-center mb-10 group-hover:scale-110 group-hover:rotate-6 transition-all duration-500 border border-white/10">
                  <Icon name={item?.icon} size={36} className="text-secondary" />
                </div>
                <h3 className="text-2xl md:text-3xl font-black text-white mb-6 leading-[1.1] italic tracking-tight">
                  {item?.message}
                </h3>
                <p className="text-lg text-slate-400 leading-relaxed font-medium">
                  {item?.description}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default MissionSection;