import React from 'react';
import Icon from '../../../components/AppIcon';

const CommunityGuidelines = ({ data }) => {
  if (!data) return null;

  return (
    <section id="guidelines" className="py-20 md:py-28 bg-[var(--color-background)] transition-colors duration-500">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-16 md:mb-24">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-100 dark:bg-emerald-900/20 rounded-full mb-6 text-emerald-700 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-800/20">
            <Icon name="BookOpen" size={20} />
            <span className="text-xs md:text-sm font-bold uppercase tracking-widest">Community Guidelines</span>
          </div>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-black text-slate-900 dark:text-white mb-6 tracking-tight italic">
            {data.title}
          </h2>
          <p className="text-base md:text-lg lg:text-xl text-slate-600 dark:text-slate-400 max-w-3xl mx-auto font-medium leading-relaxed">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-10 mb-16 md:mb-24">
          {data.items?.map((guideline, index) => (
            <div key={index} className="bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-2xl p-8 md:p-10 shadow-xl dark:shadow-none border border-white dark:border-white/10 hover:-translate-y-2 transition-all duration-500 group">
              <div className="flex items-start gap-5 mb-8">
                <div className="w-14 h-14 md:w-16 md:h-16 rounded-2xl bg-gradient-to-br from-[var(--color-brand-blue)] to-[var(--color-brand-purple)] flex items-center justify-center flex-shrink-0 shadow-lg shadow-brand-blue/20 group-hover:scale-110 transition-transform duration-500">
                  <Icon name={guideline?.icon} size={28} color="#FFFFFF" />
                </div>
                <div className="flex-1">
                  <h3 className="text-xl md:text-2xl font-black text-slate-900 dark:text-white mb-3 italic leading-tight">
                    {guideline?.title}
                  </h3>
                  <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 font-medium leading-relaxed">
                    {guideline?.description}
                  </p>
                </div>
              </div>

              <div className="space-y-4">
                {guideline?.rules?.map((rule, ruleIndex) => (
                  <div key={ruleIndex} className="flex items-start gap-4 p-4 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5">
                    <div className="w-6 h-6 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center flex-shrink-0 group-hover:bg-emerald-200 transition-colors">
                      <Icon name="Check" size={14} className="text-emerald-600 dark:text-emerald-400" />
                    </div>
                    <p className="text-sm md:text-base text-slate-700 dark:text-slate-300 font-medium leading-relaxed flex-1">
                      {rule}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="bg-gradient-to-br from-orange-50 to-red-50 dark:from-orange-950/20 dark:to-red-950/20 rounded-[2.5rem] p-8 md:p-12 lg:p-16 border border-orange-200/50 dark:border-orange-500/10 shadow-xl dark:shadow-none relative overflow-hidden transition-colors duration-500">
          <div className="absolute top-0 left-0 w-64 h-64 bg-orange-500/5 rounded-full -ml-32 -mt-32 blur-3xl"></div>

          <div className="flex flex-col lg:flex-row items-start gap-8 md:gap-12 relative z-10">
            <div className="w-20 h-20 md:w-24 md:h-24 rounded-[2rem] bg-gradient-to-br from-orange-500 to-red-600 flex items-center justify-center flex-shrink-0 shadow-xl shadow-orange-500/20">
              <Icon name="AlertCircle" size={48} className="text-white" />
            </div>
            <div className="flex-1">
              <h3 className="text-2xl md:text-3xl lg:text-4xl font-black text-slate-900 dark:text-white mb-4 tracking-tight italic">
                {data.consequences?.title}
              </h3>
              <p className="text-base md:text-lg text-slate-600 dark:text-slate-400 font-medium leading-relaxed mb-8">
                {data.consequences?.description}
              </p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {data.consequences?.levels?.map((lvl, idx) => (
                  <div key={idx} className="bg-white/50 dark:bg-white/5 backdrop-blur-md rounded-2xl p-6 border border-white dark:border-white/10 group hover:-translate-y-1 transition-all duration-300 shadow-sm hover:shadow-md">
                    <div className={`text-sm md:text-base font-black mb-2 uppercase tracking-widest ${lvl.type === 'error' ? 'text-red-600 dark:text-red-400' : 'text-orange-600 dark:text-orange-400'}`}>
                      {lvl.title}
                    </div>
                    <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 font-bold leading-relaxed">{lvl.description}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default CommunityGuidelines;