import React from 'react';
import Icon from '../../../components/AppIcon';

const DisclaimerSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-20 md:py-28 bg-[var(--color-background)] transition-colors duration-500">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-16 md:mb-24">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-rose-100 dark:bg-rose-900/20 rounded-full mb-6 text-rose-700 dark:text-rose-400 border border-rose-200 dark:border-rose-800/20">
            <Icon name="FileText" size={20} />
            <span className="text-xs md:text-sm font-bold uppercase tracking-widest">Important Disclaimers</span>
          </div>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-black text-slate-900 dark:text-white mb-6 tracking-tight italic">
            {data.title}
          </h2>
          <p className="text-base md:text-lg lg:text-xl text-slate-600 dark:text-slate-400 max-w-3xl mx-auto font-medium leading-relaxed">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-10 mb-16 md:mb-24">
          {data.items?.map((disclaimer, index) => (
            <div key={index} className="bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-3xl p-8 md:p-10 shadow-xl dark:shadow-none border border-white dark:border-white/10 hover:-translate-y-2 transition-all duration-500 group">
              <div className="flex items-start gap-5 mb-6">
                <div className="w-14 h-14 md:w-16 md:h-16 rounded-2xl bg-rose-50 dark:bg-rose-900/10 flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform shadow-sm">
                  <Icon name={disclaimer?.icon} size={28} className="text-rose-600 dark:text-rose-400" />
                </div>
                <h3 className="text-xl md:text-2xl font-black text-slate-900 dark:text-white flex-1 italic leading-tight">
                  {disclaimer?.title}
                </h3>
              </div>
              <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 font-medium leading-relaxed">
                {disclaimer?.content}
              </p>
            </div>
          ))}
        </div>

        {data.commitment && (
          <div className="bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-[2.5rem] p-8 md:p-12 lg:p-16 shadow-xl dark:shadow-none border border-white dark:border-white/10 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>

            <div className="flex flex-col lg:flex-row items-start gap-8 md:gap-12 relative z-10">
              <div className="w-20 h-20 md:w-24 md:h-24 rounded-[2rem] bg-gradient-to-br from-primary to-secondary flex items-center justify-center flex-shrink-0 shadow-xl shadow-primary/20">
                <Icon name="CheckCircle2" size={48} className="text-white" />
              </div>
              <div className="flex-1">
                <h3 className="text-2xl md:text-3xl lg:text-4xl font-black text-slate-900 dark:text-white mb-6 tracking-tight italic">
                  {data.commitment.title}
                </h3>
                <div className="space-y-6">
                  {data.commitment.items?.map((item, idx) => (
                    <div key={idx} className="flex items-start gap-4 p-5 rounded-2xl bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-white/10 transition-all duration-300">
                      <div className="w-8 h-8 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center flex-shrink-0 mt-1">
                        <Icon name={item.icon || "Check"} size={16} className="text-emerald-600 dark:text-emerald-400" />
                      </div>
                      <p className="text-sm md:text-lg text-slate-700 dark:text-slate-300 font-medium leading-relaxed">
                        <strong className="text-slate-900 dark:text-white font-black italic">{item.title}:</strong> {item.content}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="mt-12 md:mt-20 text-center">
          <p className="text-xs md:text-sm font-bold text-slate-400 dark:text-white/40 uppercase tracking-[0.2em] mb-4">
            Last updated: {data.lastUpdated ? new Date(data.lastUpdated).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : "May 16, 2026"}
          </p>
          <p className="text-sm md:text-base text-slate-500 dark:text-slate-400 font-bold">
            Questions about our disclaimers or policies? <a href="/contact" className="text-primary hover:text-secondary transition-colors italic border-b-2 border-primary/20 hover:border-secondary/20">Contact our team</a>
          </p>
        </div>
      </div>
    </section>
  );
};

export default DisclaimerSection;